// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, uint256 extra, address caller) public {
        amount = bound(amount, 1, type(uint128).max);
        extra = bound(extra, 0, type(uint128).max);
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        vm.deal(address(this), extra);
        vm.prank(address(this));
        (bool s,) = address(c).call{value: extra}("");
        require(s);

        vm.deal(caller, amount);
        vm.prank(caller);
        (bool okDeposit,) = address(c).call{value: amount}("");
        require(okDeposit);

        uint256 sumBefore = c.balances(address(this)) + c.balances(caller);
        uint256 balBefore = address(c).balance;
        vm.assume(balBefore == sumBefore);

        vm.prank(caller);
        try c.withdraw() { } catch { }

        uint256 sumAfter = c.balances(address(this)) + c.balances(caller);
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == sumAfter);
    }
}
